{
  "capabilities": [
    {
      "name": "User registration and authentication",
      "description": "Allows users to register with a username and password, log in, and end a session. Distinguishes regular users from administrators and denies access on invalid credentials or role mismatch.",
      "evidence": ["RF-01", "RF-02", "RF-03", "RF-04", "RF-07", "RNF-45"]
    },
    {
      "name": "Session identity management",
      "description": "Retains the identity of the logged-in user while navigating in the browser, until logout or local data is cleared.",
      "evidence": ["RF-05", "RNF-47"]
    },
    {
      "name": "Role-based access control",
      "description": "Restricts resource-management and catalog-administration functions to administrators; the resource-management area is shown only to administrators.",
      "evidence": ["RF-06", "RNF-46", "RNF-60"]
    },
    {
      "name": "Movie catalog browsing",
      "description": "Displays a paginated home page listing available movies with title, poster, and rating, and allows opening a movie-details page from the listing.",
      "evidence": ["RF-08", "RF-09", "RF-10", "RF-11", "RF-12", "RNF-40"]
    },
    {
      "name": "Movie details lookup",
      "description": "Provides a details page per movie showing title, rating, alternate title, release date, duration, director, screenplay, cast, synopsis, poster, and categories; prevents access to nonexistent movies.",
      "evidence": ["RF-13", "RF-14", "RF-15", "RF-16"]
    },
    {
      "name": "Category-based content discovery",
      "description": "Provides a browsing area organized by movie categories, allows viewing all categories, listing only movies of a selected category, and returning to the overall catalog view.",
      "evidence": ["RF-17", "RF-18", "RF-19", "RF-21"]
    },
    {
      "name": "Movie playback and file download",
      "description": "Allows starting playback from the movie details page and provides a download link when the resource is ready; ensures the video file is available in the delivery area, obtaining it from the configured local repository if needed.",
      "evidence": ["RF-22", "RF-23", "RF-24", "RF-25"]
    },
    {
      "name": "Catalog administration",
      "description": "Allows administrators to register new movies with required metadata, upload movie video files, delete individual or multiple movies, and prevents duplicate or nonexistent movie operations.",
      "evidence": ["RF-26", "RF-27", "RF-28", "RF-29", "RF-30", "RF-31", "RF-32", "RF-33"]
    },
    {
      "name": "Registration consistency enforcement",
      "description": "Prevents duplicate user registration by username and duplicate movie registration by title; treats movie title as the unique catalog identifier.",
      "evidence": ["RF-34", "RF-35", "RNF-43"]
    },
    {
      "name": "Persistent data storage",
      "description": "Persistently stores user, movie, and category information in a structured database supporting catalog relationships.",
      "evidence": ["RNF-42", "RNF-54"]
    },
    {
      "name": "Consistent API response handling",
      "description": "Maintains a consistent response format indicating status, message, and returned data, and returns controlled error messages whenever possible.",
      "evidence": ["RNF-41", "RNF-44"]
    },
    {
      "name": "Media and storage management",
      "description": "Supports large video uploads up to 2 GB, treats MP4 as the standard format, and provides a local area for temporary storage/serving and a configured local repository for on-demand loading.",
      "evidence": ["RNF-48", "RNF-49", "RNF-50", "RNF-51"]
    },
    {
      "name": "Independent UI and service evolution",
      "description": "Allows the user interface and application services to evolve independently and for the UI to consume services even when deployed in a different environment.",
      "evidence": ["RNF-52", "RNF-53"]
    }
  ],
  "domain_entities": [
    "User",
    "Movie",
    "Category",
    "Cast member",
    "Video file"
  ],
  "business_rules": [
    "Users must register with a username and password; duplicate usernames are not allowed (RF-01, RF-34).",
    "At least two user roles exist: regular user and administrator (RF-03, RNF-45).",
    "Access is denied when the user does not exist, the password is incorrect, or the stated role does not match the registration (RF-04).",
    "Catalog-management functions are restricted to the administrator role (RF-06, RNF-46).",
    "A movie title is the unique identifier for catalog registration; duplicate titles are not allowed (RF-28, RF-35).",
    "A movie must belong to at least one category and may belong to more than one category (RF-20, RNF-56).",
    "Movie registration must include at minimum title, rating, alternate title, release date, duration, director, screenplay, cast, categories, synopsis, and poster (RF-27).",
    "Deletion of nonexistent movies must be prevented (RF-33).",
    "Before batch deletion, the administrator must be informed which movies have been selected (RF-32).",
    "Playback requires the video file to be available in the delivery area; if not, the system must attempt to obtain it from the configured local repository (RF-24, RF-25).",
    "Automatic playback depends on the existence of an MP4 file corresponding to the registered title, and the source filename must follow the expected pattern (RNF-58, RNF-59).",
    "Uploading the video file and registering the movie are related but independent steps (RNF-57).",
    "The catalog must be displayed in pages of up to 12 movies (RNF-40).",
    "User, movie, and category information must be persistently stored, preserving uniqueness to prevent duplicates (RNF-42, RNF-43).",
    "Operations must return a consistent response format with status, message, and data, and controlled error messages whenever possible (RNF-41, RNF-44)."
  ],
  "unresolved_questions": [
    "The backend does not fully validate the administrator restriction for resource management, despite the interface intention (RNF-60).",
    "The exact filename pattern expected by the environment configuration for automatic loading is not specified (RNF-59).",
    "The mechanism for obtaining video files from the configured local repository is not detailed (RF-25, RNF-51).",
    "The scope of 'resource-management area' and its exact functions beyond catalog administration are not fully defined (RF-06).",
    "Whether categories can be created or managed by administrators is not stated in the provided requirements."
  ]
}

